function calcularZAVIC_CXP(respuestas) {
  /*
   * respuestas: array de objetos { id: 'Z01', mas: 'A', menos: 'C' }
   * Retorna: { L, M, I, C, etica_combinada } + { veredicto, descarte_motivos, alertas }
   * DIFERENCIA VS ZAVIC OPERATIVO:
   *   - Posiciones randomizadas: usa mapa específico por ítem
   *   - I y C suman cuando el candidato las ELIGE como MÁS (no cuando las rechaza)
   *   - La selección MENOS no produce puntos en ninguna dimensión
   *   - Umbrales más estrictos: Corrupción ≥ 14 = DESCARTE, Indiferencia ≥ 27 = DESCARTE
   */
  const MAPA = {
    Z01: { A: 'L', B: 'M', C: 'I', D: 'C' },
    Z02: { A: 'M', B: 'I', C: 'C', D: 'L' },
    Z03: { A: 'I', B: 'C', C: 'L', D: 'M' },
    Z04: { A: 'C', B: 'L', C: 'M', D: 'I' },
    Z05: { A: 'L', B: 'I', C: 'M', D: 'C' },
    Z06: { A: 'M', B: 'C', C: 'L', D: 'I' },
    Z07: { A: 'I', B: 'L', C: 'C', D: 'M' },
    Z08: { A: 'C', B: 'M', C: 'I', D: 'L' },
    Z09: { A: 'L', B: 'C', C: 'M', D: 'I' },
    Z10: { A: 'M', B: 'I', C: 'L', D: 'C' },
    Z11: { A: 'I', B: 'M', C: 'C', D: 'L' },
    Z12: { A: 'C', B: 'I', C: 'L', D: 'M' },
    Z13: { A: 'L', B: 'M', C: 'C', D: 'I' },
    Z14: { A: 'M', B: 'L', C: 'I', D: 'C' },
    Z15: { A: 'C', B: 'L', C: 'I', D: 'M' }
  };

  const scores = { L: 0, M: 0, I: 0, C: 0 };

  respuestas.forEach(function(r) {
    var dim_mas = MAPA[r.id][r.mas];
    scores[dim_mas] += 2;
    // La seleccion MENOS no produce puntos en ninguna dimension
  });

  var normalizado = {};
  Object.keys(scores).forEach(function(k) {
    normalizado[k] = Math.round(scores[k] / 30 * 100);
  });

  var etica_combinada = Math.round((scores.L + scores.M) / 30 * 100);

  var descarte_motivos = [];
  if (etica_combinada < 55) descarte_motivos.push('Etica combinada insuficiente: ' + etica_combinada);
  if (normalizado.I >= 27) descarte_motivos.push('Indiferencia elevada: ' + normalizado.I);
  if (normalizado.C >= 14) descarte_motivos.push('Corrupcion detectada: ' + normalizado.C);

  var alertas = [];
  if (etica_combinada >= 55 && etica_combinada < 75) alertas.push('Etica combinada en zona de atencion: ' + etica_combinada);
  if (normalizado.I >= 14 && normalizado.I < 27) alertas.push('Indiferencia: senal de atencion: ' + normalizado.I);
  if (normalizado.C >= 7 && normalizado.C < 14) alertas.push('Corrupcion: senal de atencion — revisar en entrevista: ' + normalizado.C);

  var veredicto = descarte_motivos.length > 0 ? 'DESCARTE' :
                  alertas.length > 0 ? 'ALERTA' : 'PASA';

  return {
    puntajes: normalizado,
    etica_combinada: etica_combinada,
    veredicto: veredicto,
    descarte_motivos: descarte_motivos,
    alertas: alertas
  };
}
